<script setup>
import { onMounted, ref, computed, watch, nextTick } from 'vue'
import { useRouter } from 'vue-router'
import { apiFetch } from '../services/api.js'
import CargaMultimedia from './CargaMultimedia.vue'
import IconoForo from './IconoForo.vue'
import CampoUrlImagen from './CampoUrlImagen.vue'
const props=defineProps({categorias:{type:Array,default:()=>[]}}),emit=defineEmits(['cerrar','creada'])
const router=useRouter(),modal=ref(null),paso=ref(1),error=ref(''),ocupado=ref(false)
const iconoCarga=ref(null),portadaCarga=ref(null),nIcono=ref(0),nPortada=ref(0),prevIcono=ref(''),prevPortada=ref('')
const datos=ref({id_categoria:null,tipo:'publica',nombre:'',slug:'',descripcion:'',icono_url:'',portada_url:'',normas:''})
const modoIcono=ref("archivo"),modoPortada=ref("archivo")
const tema=computed(()=>props.categorias.find(c=>c.id===datos.value.id_categoria)?.nombre||"Temática")
const tipos=[{id:"publica",nombre:"Pública",icono:"globo",texto:"Todos pueden leer; los usuarios autenticados pueden participar."},{id:"restringida",nombre:"Restringida",icono:"ojo",texto:"Todos pueden leer; solo miembros aprobados pueden participar."},{id:"privada",nombre:"Privada",icono:"candado",texto:"No disponible por el momento.",disabled:true}]
function cerrar(){if(!ocupado.value&&(!(nIcono.value||nPortada.value)||confirm('¿Cancelar y descartar los archivos seleccionados?')))emit('cerrar')}
onMounted(()=>modal.value?.showModal())
watch(paso,async()=>{await nextTick();const area=modal.value?.querySelector('.comunidad-paso-contenido');if(area)area.scrollTop=0})
function avanzar(){error.value='';if(paso.value===1&&!datos.value.id_categoria){error.value='Selecciona una temática.';return}if(paso.value===3&&(!/^[a-z0-9][a-z0-9_-]{2,39}$/.test(datos.value.slug)||datos.value.nombre.trim().length<3||!datos.value.descripcion.trim())){error.value='Completa el nombre, descripción e identificador (3 a 40 caracteres: letras minúsculas, números, guion o guion bajo).';return}paso.value++}
async function crear(){ocupado.value=true;error.value='';try{const d={...datos.value};if(modoIcono.value==='archivo')d.icono_url='';if(modoPortada.value==='archivo')d.portada_url='';if(modoIcono.value==='archivo'&&nIcono.value)d.icono_archivo=(await iconoCarga.value.preparar())[0];if(modoPortada.value==='archivo'&&nPortada.value)d.portada_archivo=(await portadaCarga.value.preparar())[0];const r=await apiFetch('foro','/comunidades',{method:'POST',body:JSON.stringify(d)});emit('creada');emit('cerrar');await router.push(`/comunidades/${r.slug}`)}catch(e){error.value=e.message}finally{ocupado.value=false}}
</script>
<template>
<Teleport to="body"><dialog ref="modal" class="comunidad-dialogo panel-lateral" aria-labelledby="titulo-comunidad" @cancel.prevent="cerrar">
  <header class="comunidad-dialogo-header"><div><small>Paso {{paso}} de 4</small><h2 id="titulo-comunidad">Crear comunidad</h2><p>Construye un espacio para compartir conocimiento.</p></div><button class="btn-icono" type="button" aria-label="Cerrar" :disabled="ocupado" @click="cerrar"><IconoForo nombre="cerrar"/></button><div class="pasos-comunidad" role="progressbar" aria-label="Progreso" :aria-valuenow="paso" aria-valuemin="1" aria-valuemax="4"><span v-for="n in 4" :key="n" :class="{'paso-listo':n<=paso}"></span></div></header>
  <form @submit.prevent="paso<4?avanzar():crear()" class="comunidad-pasos-form">
    <div class="comunidad-paso-contenido">
    <div v-if="paso===1" class="paso-contenido"><h3>Elige una temática</h3><p class="nota-demo">Selecciona la categoría que mejor describe tu comunidad.</p><div class="chips"><button v-for="c in props.categorias" :key="c.id" type="button" class="chip" :class="{'chip-activo':datos.id_categoria===c.id}" :aria-pressed="datos.id_categoria===c.id" @click="datos.id_categoria=c.id"><IconoForo :nombre="datos.id_categoria===c.id?'check':'explorar'"/>{{c.nombre}}</button></div><p v-if="!props.categorias.length" class="foro-vacio">No hay categorías disponibles.</p></div>
    <div v-else-if="paso===2" class="paso-contenido"><h3>Tipo de comunidad</h3><p class="nota-demo">Define quién puede participar.</p><fieldset class="opciones-comunidad"><legend class="ux-sr">Tipo de comunidad</legend><label v-for="t in tipos" :key="t.id" class="opcion-comunidad" :class="{'opcion-elegida':datos.tipo===t.id,'opcion-deshabilitada':t.disabled}"><IconoForo :nombre="t.icono"/><span><strong>{{t.nombre}}</strong><small>{{t.texto}}</small></span><input type="radio" :value="t.id" v-model="datos.tipo" :disabled="t.disabled"></label></fieldset></div>
    <div v-else-if="paso===3" class="paso-contenido"><h3>Dale una identidad</h3><div class="comunidad-doble"><div class="ux-campos"><label>Nombre<input v-model="datos.nombre" required minlength="3" maxlength="60" placeholder="Nombre de la comunidad"><small class="contador">{{datos.nombre.length}}/60</small></label><label>Identificador<input v-model="datos.slug" required pattern="[a-z0-9][a-z0-9_\-]{2,39}" maxlength="40" placeholder="mi-comunidad"><small class="contador">/comunidades/{{datos.slug}} · {{datos.slug.length}}/40</small></label><label>Descripción<textarea v-model="datos.descripcion" maxlength="500" required rows="3"></textarea><small class="contador">{{datos.descripcion.length}}/500</small></label></div><aside class="comunidad-preview"><small>Vista previa</small><div class="preview-portada"><img v-if="modoPortada==='archivo'?prevPortada:datos.portada_url.startsWith('https://')" :src="modoPortada==='archivo'?prevPortada:datos.portada_url" alt="" referrerpolicy="no-referrer"></div><span class="preview-avatar"><img v-if="modoIcono==='archivo'?prevIcono:datos.icono_url.startsWith('https://')" :src="modoIcono==='archivo'?prevIcono:datos.icono_url" alt="" referrerpolicy="no-referrer"><IconoForo v-else nombre="usuarios"/></span><strong>{{datos.nombre||'Tu comunidad'}}</strong><small>/comunidades/{{datos.slug||'identificador'}} · {{tema}}</small><p>{{datos.descripcion||'Describe tu comunidad aquí.'}}</p></aside></div></div>
    <div v-show="paso===4" class="paso-contenido"><h3>Personalización opcional</h3><p class="nota-demo">Puedes añadir imágenes ahora o editar la comunidad más tarde.</p><div class="comunidad-doble">
      <section class="ux-campos"><h4>Icono</h4><div class="ux-segmentos" role="group" aria-label="Origen del icono"><button v-for="m in ['archivo','url']" :key="m" type="button" :aria-pressed="modoIcono===m" :disabled="ocupado" @click="modoIcono=m">{{m==='archivo'?'Dispositivo':'URL HTTPS'}}</button></div><CargaMultimedia v-show="modoIcono==='archivo'" ref="iconoCarga" tipo="multimedia" uso="icono" :bloqueado="ocupado" @cambio="(n,url)=>{nIcono=n;prevIcono=url}"/><CampoUrlImagen v-if="paso===4&&modoIcono==='url'" v-model="datos.icono_url" etiqueta="Icono (URL HTTPS)" :bloqueado="ocupado"/></section>
      <section class="ux-campos"><h4>Portada</h4><div class="ux-segmentos" role="group" aria-label="Origen de la portada"><button v-for="m in ['archivo','url']" :key="m" type="button" :aria-pressed="modoPortada===m" :disabled="ocupado" @click="modoPortada=m">{{m==='archivo'?'Dispositivo':'URL HTTPS'}}</button></div><CargaMultimedia v-show="modoPortada==='archivo'" ref="portadaCarga" tipo="multimedia" uso="portada" :bloqueado="ocupado" @cambio="(n,url)=>{nPortada=n;prevPortada=url}"/><CampoUrlImagen v-if="paso===4&&modoPortada==='url'" v-model="datos.portada_url" etiqueta="Portada (URL HTTPS)" :bloqueado="ocupado"/></section></div><label>Normas<textarea v-model="datos.normas" maxlength="2000" rows="3" placeholder="Normas de convivencia (opcional)"></textarea><small class="contador">{{datos.normas.length}}/2000</small></label></div>
    <p v-if="error" class="error" role="alert">{{error}}</p></div>
    <footer class="comunidad-dialogo-footer"><button type="button" class="btn-texto" :disabled="ocupado" @click="cerrar">Cancelar</button><span class="ux-flex-spacer"></span><button v-if="paso>1" type="button" class="btn-secundario" :disabled="ocupado" @click="paso--;error=''">Atrás</button><button class="btn-primario btn-ancho-auto" :disabled="ocupado" type="submit">{{ocupado?'Creando…':paso===4?'Crear comunidad':'Siguiente'}}</button></footer>
  </form>
</dialog></Teleport>
</template>
